class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def singlevalued(self, root: TreeNode) -> int:
        count = [0]

        def dfs(node):
            if node is None:
                return True

            left_unival = dfs(node.left)
            right_unival = dfs(node.right)

            if left_unival and right_unival:
                if node.left and node.left.val != node.val:
                    return False
                if node.right and node.right.val != node.val:
                    return False
                count[0] += 1
                return True

            return False

        dfs(root)
        return count[0]
